(7473454, 1186956, 163081, '<td valign="top">The darkness inside the temple makes me hungry to see more. Mysterious and alive. Probably the winner. A 9 from me</td>', 'The darkness inside the temple makes me hungry to see more. Mysterious and alive. Probably the winner. A 9 from me', '2016-09-09 11:35:25.000000', NULL, 1),
